  constructor(x, y, size, rotation) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.rotation = rotation;
  }
  display() {
    cg.push();
      cg.translate(this.x, this.y);
      cg.scale(this.size);
      cg.rotate(this.rotation);
      cg.noStroke();
      for (let typo of typos01) {
        typo.display();
      }
    cg.pop();
  }
}
